import * as globals from "#base/maps/map-globals.js";
import * as utilities from "#base/maps/map-utilities.js";

export function designateBiomes(iWidth: number, iHeight: number) {
	console.log("Biomes");

	let iTotalLandPlots = 0;
	let iTotalLandPlotsAbove = 0;
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const latitude: number = GameplayMap.getPlotLatitude(iX, iY);
			if (!GameplayMap.isWater(iX, iY)) {
				iTotalLandPlots = iTotalLandPlots + 1;
			}

			if (!GameplayMap.isWater(iX, iY) && globals.g_PlainsLatitude < latitude) {
				iTotalLandPlotsAbove = iTotalLandPlotsAbove + 1;
			}
		}
	}

	let _iPlainsLowering = 0;
	let _iDesertLowering = 0;
	let _iGrassLowering = 0;
	let _iTropicalLowering = 0;

	if (Math.round((iTotalLandPlots / 5.0) * 2.0 * 0.75) > iTotalLandPlotsAbove) {
		_iPlainsLowering += 5;
		_iDesertLowering += 4;
		_iGrassLowering += 4;
		_iTropicalLowering += 2;
		console.log(
			"Less " + " iTotalLandPlots: " + iTotalLandPlots + " iTotalLandPlotsAbove: " + iTotalLandPlotsAbove,
		);
	}

	//Actually designate biomes
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			if (GameplayMap.isWater(iX, iY)) {
				TerrainBuilder.setBiomeType(iX, iY, globals.g_MarineBiome);
			} else {
				let latitude: number = GameplayMap.getPlotLatitude(iX, iY);

				if (latitude < 0) latitude = -1 * latitude;

				latitude += Math.round(GameplayMap.getElevation(iX, iY) / 120.0);

				/* Old Stripe version
				if (GameplayMap.isRiver(iX, iY)) {
					latitude -= 10;
				} else if (GameplayMap.isAdjacentToRivers(iX, iY, 1)) {
					latitude -= 5;
				}

				const rainfall: number = GameplayMap.getRainfall(iX, iY);
				if (latitude < globals.g_TropicalLatitude - iTropicalLowering && rainfall < 85) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_PlainsBiome);
				} else if (latitude < globals.g_TropicalLatitude - iTropicalLowering) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_TropicalBiome);
				} else if (
					latitude < globals.g_PlainsLatitude - iPlainsLowering ||
					(latitude < globals.g_TropicalLatitude - iTropicalLowering && rainfall < 85)
				) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_PlainsBiome);
				} else if (
					latitude < globals.g_DesertLatitude - iDesertLowering ||
					(latitude < globals.g_PlainsLatitude - iPlainsLowering && rainfall < 85)
				) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_DesertBiome);
				} else if (latitude < globals.g_GrasslandLatitude - iGrassLowering) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_GrasslandBiome);
				} else {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_TundraBiome);
				}
				*/

				// Rainfall based approach
				// Biome Order from in to out is Tropical-Plains-Desert-Grassland-Tundra
				//Numbers are 					 17		  33	 44		58		  ??
				//Diffs are					 17		  16	  11	 14		  ??
				//Deserts now auto hit on low rainfall

				const rainfall: number = GameplayMap.getRainfall(iX, iY);

				//if rainfall is below minimum, auto set to desert. If above maximum, auto set to tropical
				if (rainfall < 25) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_DesertBiome);
				} else if (rainfall > 250 && !(GameplayMap.getTerrainType(iX, iY) == globals.g_MountainTerrain)) {
					TerrainBuilder.setBiomeType(iX, iY, globals.g_TropicalBiome);
				}

				//Otherwise, adjust latitude based on rainfall and elevation
				else {
					if (rainfall < 100) {
						latitude += (100 - rainfall) / 10;
					} else if (rainfall > 100) {
						latitude -= (rainfall - 100) / 10;
					}

					if (GameplayMap.isRiver(iX, iY)) {
						latitude -= 10;
					} else if (GameplayMap.isAdjacentToRivers(iX, iY, 1)) {
						latitude -= 5;
					}

					/*if (GameplayMap.getElevation(iX, iY) > 1200) { latitude += 20; }
					else if (GameplayMap.getElevation(iX, iY) > 1000) { latitude += 10; }
					else if (GameplayMap.getElevation(iX, iY) > 800) { latitude += 5; }*/

					//Then assign biome based on pseudolatitude
					if (latitude < 17) {
						TerrainBuilder.setBiomeType(iX, iY, globals.g_TropicalBiome);
					} else if (latitude < 33) {
						TerrainBuilder.setBiomeType(iX, iY, globals.g_PlainsBiome);
					} else if (latitude < 44) {
						TerrainBuilder.setBiomeType(iX, iY, globals.g_DesertBiome);
					} else if (latitude < 58) {
						TerrainBuilder.setBiomeType(iX, iY, globals.g_GrasslandBiome);
					} else {
						TerrainBuilder.setBiomeType(iX, iY, globals.g_TundraBiome);
					}
				}
			}
		}
	}
}

export function addFeatures(iWidth: number, iHeight: number) {
	console.log("Features");
	addPositionalFeatures(iWidth, iHeight);
	scatterFeatures(iWidth, iHeight);
	addIce(iWidth, iHeight);
	addAquaticFeatures(iWidth, iHeight);
}

function addPositionalFeatures(iWidth: number, iHeight: number) {
	// Find next specific position
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			//let _biome: BiomeType = GameplayMap.getBiomeType(iX, iY);
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);

			if (
				GameplayMap.isWater(iX, iY) == false &&
				feature == FeatureTypes.NO_FEATURE &&
				GameplayMap.isNavigableRiver(iX, iY) == false
			) {
				// Along coast?
				if (GameplayMap.isCoastalLand(iX, iY)) {
					// See if we can scatter a feature here
					for (var featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
						if (
							canAddFeature(
								iX,
								iY,
								featIdx,
								false /*bScatterable*/,
								false /*bRiverMouth*/,
								true /*bCoastal*/,
								false /*bNearRiver*/,
								false /*bIsolated*/,
								false /*bReef*/,
								false /*bIce*/,
								false /*bInLake*/,
								false /*bOpenWaters*/,
							)
						) {
							AddFeature(iX, iY, featIdx, 100, "Feature Scatter");
							break;
						}
					}
				}

				// Near multiple river hexes?
				else if (GameplayMap.isAdjacentToRivers(iX, iY, 2)) {
					// See if we can scatter a feature here
					for (var featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
						if (
							canAddFeature(
								iX,
								iY,
								featIdx,
								false /*bScatterable*/,
								false /*bRiverMouth*/,
								false /*bCoastal*/,
								true /*bNearRiver*/,
								false /*bIsolated*/,
								false /*bReef*/,
								false /*bIce*/,
								false /*bInLake*/,
								false /*bOpenWaters*/,
							)
						) {
							AddFeature(iX, iY, featIdx, 100, "Feature Scatter");
							break;
						}
					}
				}

				// Away from water?
				else {
					if (GameplayMap.isAdjacentToRivers(iX, iY, 1)) {
						continue;
					} else if (GameplayMap.isCoastalLand(iX, iY)) {
						continue;
					}

					for (var featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
						// Must not already be in an adjacent plot
						if (
							!GameplayMap.isAdjacentToFeature(iX, iY, featIdx) &&
							canAddFeature(
								iX,
								iY,
								featIdx,
								false /*bScatterable*/,
								false /*bRiverMouth*/,
								false /*bCoastal*/,
								false /*bNearRiver*/,
								true /*bIsolated*/,
								false /*bReef*/,
								false /*bIce*/,
								false /*bInLake*/,
								false /*bOpenWaters*/,
							)
						) {
							AddFeature(iX, iY, featIdx, 100, "Feature Scatter");
							break;
						}
					}
				}
			}
		}
	}
}

function scatterFeatures(iWidth: number, iHeight: number) {
	// Find spots and use PlacementDensity to decide whether or not to place it
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);

			if (
				GameplayMap.isWater(iX, iY) == false &&
				feature == FeatureTypes.NO_FEATURE &&
				GameplayMap.isNavigableRiver(iX, iY) == false
			) {
				// See if we can scatter a feature here
				for (let featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
					if (
						canAddFeature(
							iX,
							iY,
							featIdx,
							true /*bScatterable*/,
							false /*bRiverMouth*/,
							false /*bCoastal*/,
							false /*bNearRiver*/,
							false /*bIsolated*/,
							false /*bReef*/,
							false /*bIce*/,
							false /*bInLake*/,
							false /*bOpenWaters*/,
						)
					) {
						AddFeature(iX, iY, featIdx, 100, "Feature Scatter");
						break;
					}
				}
			}
		}
	}
}

function addAquaticFeatures(iWidth: number, iHeight: number) {
	//Add Reefs
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);

			if (GameplayMap.isWater(iX, iY) == true && feature == FeatureTypes.NO_FEATURE) {
				let latitude: number = GameplayMap.getPlotLatitude(iX, iY);
				if (latitude < 0) latitude = -1 * latitude;

				for (let featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
					if (
						canAddFeature(
							iX,
							iY,
							featIdx,
							false /*bScatterable*/,
							false /*bRiverMouth*/,
							false /*bCoastal*/,
							false /*bNearRiver*/,
							false /*bIsolated*/,
							true /*bReef*/,
							false /*bIce*/,
							false /*bInLake*/,
							false /*bOpenWaters*/,
						)
					) {
						if (
							GameInfo.Features[featIdx].MinLatitude <= latitude &&
							GameInfo.Features[featIdx].MaxLatitude > latitude
						) {
							const iWeight: number = (latitude + 50) * 2;
							AddFeature(iX, iY, featIdx, iWeight, "Feature Reef");
							break;
						}
					}
				}
			}
		}
	}
	//Add Atolls
	const skipPlotIndices: number[] = [];
	let skipPlot = false;

	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);

			for (const skipPlotIndex of skipPlotIndices) {
				const plot: PlotCoord = GameplayMap.getLocationFromIndex(skipPlotIndex);
				// INVESTIGATE - Is this a bug?  Was this supposed to be `plot.y == iY`?
				if (plot.x == iX && plot.y && iY) {
					skipPlot = true;
					break;
				}
			}
			if (!skipPlot) {
				if (GameplayMap.isWater(iX, iY) == true && feature == FeatureTypes.NO_FEATURE) {
					let latitude: number = GameplayMap.getPlotLatitude(iX, iY);
					if (latitude < 0) latitude = -1 * latitude;

					for (let featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
						if (
							canAddFeature(
								iX,
								iY,
								featIdx,
								false /*bScatterable*/,
								false /*bRiverMouth*/,
								false /*bCoastal*/,
								false /*bNearRiver*/,
								false /*bIsolated*/,
								false /*bReef*/,
								false /*bIce*/,
								false /*bInLake*/,
								true /*bOpenWaters*/,
							)
						) {
							if (
								GameInfo.Features[featIdx].MinLatitude <= latitude &&
								GameInfo.Features[featIdx].MaxLatitude > latitude
							) {
								if (shallowWaterAdjacencyCheck(iX, iY, "Feature Atoll Spawn Chance")) {
									AddFeature(iX, iY, featIdx, 100, "Feature Atoll");

									const neighbors = GameplayMap.getPlotIndicesInRadius(iX, iY, 1);
									const iRollForClusterSize = TerrainBuilder.getRandomNumber(
										neighbors.length,
										"Feature Atoll Size",
									);
									const growthChancePercent = latitude <= 15 && latitude >= -15 ? 15 : 5; //Higher chance to "grow" this Atoll area near the Equator

									//"Grow" this Atoll area
									for (let plotIndex = 0; plotIndex < iRollForClusterSize; ++plotIndex) {
										const iLocation: PlotCoord = GameplayMap.getLocationFromIndex(
											neighbors[plotIndex],
										);
										if (
											canAddFeature(
												iLocation.x,
												iLocation.y,
												featIdx,
												false /*bScatterable*/,
												false /*bRiverMouth*/,
												false /*bCoastal*/,
												false /*bNearRiver*/,
												false /*bIsolated*/,
												false /*bReef*/,
												false /*bIce*/,
												false /*bInLake*/,
												true /*bOpenWaters*/,
											)
										) {
											if (
												shallowWaterAdjacencyCheck(
													iLocation.x,
													iLocation.y,
													"Feature Atoll Spawn Chance",
												)
											) {
												const iRoll = TerrainBuilder.getRandomNumber(100, "Feature Atoll");
												if (iRoll < growthChancePercent) {
													AddFeature(iLocation.x, iLocation.y, featIdx, 30, "Feature Atoll");

													//Skip this plot in the next iteration, since we've already added another Atoll to it
													skipPlotIndices.push(neighbors[plotIndex]);
												}
											}
										}
									}
								}
								break;
							}
						}
					}
				}
			} else {
				skipPlot = false;
				continue;
			}
		}
	}
	//Add Lotuses
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);
			if (GameplayMap.isWater(iX, iY) == true && feature == FeatureTypes.NO_FEATURE) {
				for (let featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
					if (
						canAddFeature(
							iX,
							iY,
							featIdx,
							false /*bScatterable*/,
							false /*bRiverMouth*/,
							false /*bCoastal*/,
							false /*bNearRiver*/,
							false /*bIsolated*/,
							false /*bReef*/,
							false /*bIce*/,
							true /*bInLake*/,
							false /*bOpenWaters*/,
						)
					) {
						AddFeature(iX, iY, featIdx, 100, "Feature Lotus");
						break;
					}
				}
			}
		}
	}
}

function AddFeature(x: number, y: number, iCurrentFeatureIndex: number, iRandomRollMax: number, logMsg: string) {
	const iScatterChance = GameInfo.Features[iCurrentFeatureIndex].PlacementDensity;
	const iRoll = TerrainBuilder.getRandomNumber(iRandomRollMax, logMsg);
	if (iRoll < iScatterChance) {
		const featureParam = {
			Feature: iCurrentFeatureIndex,
			Direction: -1,
			Elevation: 0,
		};
		TerrainBuilder.setFeatureType(x, y, featureParam);
	}
}

function shallowWaterAdjacencyCheck(x: number, y: number, log: string) {
	//If adjacent to coastal terrain - let the spawn chance to be 30%
	if (GameplayMap.isAdjacentToShallowWater(x, y)) {
		const spawnChance = TerrainBuilder.getRandomNumber(100, log);
		return spawnChance < 30;
	}

	return true;
}

function addIce(iWidth: number, iHeight: number) {
	// Find spots and use PlacementDensity to decide whether or not to place it
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const feature: FeatureType = GameplayMap.getFeatureType(iX, iY);

			if (GameplayMap.isWater(iX, iY) == true && feature == FeatureTypes.NO_FEATURE) {
				// See if we can scatter a feature here
				let latitude: number = GameplayMap.getPlotLatitude(iX, iY);
				if (latitude < 0) latitude = -1 * latitude - 5;

				if (latitude > 78) {
					for (let featIdx = 0; featIdx < GameInfo.Features.length; featIdx++) {
						if (
							canAddFeature(
								iX,
								iY,
								featIdx,
								false /*bScatterable*/,
								false /*bRiverMouth*/,
								false /*bCoastal*/,
								false /*bNearRiver*/,
								false /*bIsolated*/,
								false /*bReef*/,
								true /*bIce*/,
								false /*bInLake*/,
								false /*bOpenWaters*/,
							)
						) {
							const iScatterChance = GameInfo.Features[featIdx].PlacementDensity;
							let iScore: number = TerrainBuilder.getRandomNumber(100, "Feature Ice");
							iScore = iScore + latitude;

							if (GameplayMap.isAdjacentToLand(iX, iY)) {
								iScore = 0;
							}

							if (utilities.isAdjacentToNaturalWonder(iX, iY)) {
								iScore = 0;
							}

							if (iScore > iScatterChance) {
								const featureParam = {
									Feature: featIdx,
									Direction: -1,
									Elevation: 0,
								};
								TerrainBuilder.setFeatureType(iX, iY, featureParam);
								break;
							}
						}
					}
				}
			}
		}
	}
}

function canAddFeature(
	iX: number,
	iY: number,
	feature: number,
	bScatterable: boolean,
	bRiverMouth: boolean,
	bCoastal: boolean,
	bNearRiver: boolean,
	bIsolated: boolean,
	bReef: boolean,
	bIce: boolean,
	bInLake: boolean,
	bOpenWaters: boolean,
): boolean {
	// Check DB to see if this is scatterable
	if (!bScatterable || GameInfo.Features[feature].PlacementClass == "SCATTER") {
		if (!bRiverMouth || GameInfo.Features[feature].PlacementClass == "RIVERMOUTH") {
			if (!bCoastal || GameInfo.Features[feature].PlacementClass == "COASTAL") {
				if (!bNearRiver || GameInfo.Features[feature].PlacementClass == "NEARRIVER") {
					if (!bIsolated || GameInfo.Features[feature].PlacementClass == "ISOLATED") {
						if (!bReef || GameInfo.Features[feature].PlacementClass == "REEF") {
							if (!bInLake || GameInfo.Features[feature].PlacementClass == "IN_LAKE") {
								if (!bOpenWaters || GameInfo.Features[feature].PlacementClass == "OPEN_WATERS")
									if (!bIce || GameInfo.Features[feature].PlacementClass == "ICE") {
										return TerrainBuilder.canHaveFeature(iX, iY, feature);
									}
							}
						}
					}
				}
			}
		}
	}

	return false;
}
